// READ-ONLY monitor for PORTFOLIO-DEMO-001. Never starts Codex or writes Worker Task State.
// Start this monitor after the main EXECUTE task has created its Worker Task State.
const stage_titles = {
  'CARD13.1': 'Card catalog and instance identity',
  'CARD13.2': 'Per-player draw, hand, discard and reshuffle',
  'CARD13.3': 'Reusable effect composition, card-play transaction, Fuel',
  'CARD13.4': 'Drive keyword and automatic legal Next JunctionIntent',
  'CARD13.5': 'Intent Change keyword',
  'CARD13.6': 'Lane Switch keyword and shared lane topology',
  'CARD13.7': 'Honk keyword and civilian WORLD-plan replacement',
  'CARD13.8': 'Assemble all five cards from shared keywords',
  'CARD13.9': 'Stable read/write gameplay ↔ HUD boundary',
  'CARD13.10': '1P Green City card-driven match loop and integration-ready handoff',
};
return [{json:{
  task_id:'PORTFOLIO-DEMO-001',
  worker_base_url:'http://127.0.0.1:47834',
  poll_seconds:15,
  started_at:new Date().toISOString(),
  max_monitor_minutes:360,
  stage_titles,
  stage_order:Object.keys(stage_titles),
  stage_count:Object.keys(stage_titles).length
}}];

const cfg = $('Monitor Settings').first().json;
const raw = $input.first().json;
const body = raw?.body && typeof raw.body === 'object' ? raw.body : raw;
const observed_at = new Date().toISOString();
const http_status = Number(raw?.statusCode ?? 0);
const elapsed = (Date.now() - new Date(cfg.started_at).getTime()) / 60000;
const result = (details) => [{json:{task_id:cfg.task_id,observed_at,http_status,...details}}];
// Read-only; if run too early, stop without creating a task.
if ([400,404].includes(http_status) && body?.message === 'Task State does not exist.') {
  return result({status:'NOT_STARTED',progress_label:'No Worker Task State yet; run the main EXECUTE workflow first',monitoring:false});
}
if (http_status !== 200 || body?.status !== 'ok' || body?.task_id !== cfg.task_id) {
  return result({status:'MONITOR_ERROR',progress_label:'Cannot read authorized Worker Task State',
    reason:String(body?.message || body?.reason || 'unexpected status').slice(0,350),monitoring:false});
}
const completed = Array.isArray(body.completed_stages) ? body.completed_stages : [];
const active = typeof body.iteration_id === 'string' && body.iteration_id.trim()
  ? body.iteration_id : null;
const last = body.last_iteration && typeof body.last_iteration === 'object' ? body.last_iteration : null;
const stageId = body.stage_id || (active ? active.replace(/\.[A-Z]+$/,'') : null) ||
  cfg.stage_order[Math.min(completed.length, cfg.stage_order.length-1)];
const stageTitle = cfg.stage_titles[stageId] || stageId || 'Unknown stage';
const lastId = last?.iteration_id || null;
const lastTitle = last?.change_title || last?.short_change_title || last?.title || null;
const lastLabel = lastId ? `${lastId} — ${lastTitle || (cfg.stage_titles[lastId.replace(/\.[A-Z]+$/,'')] || 'last iteration')}` : null;
const reportedTitle = body.current_iteration_title || body.iteration_title ||
  (typeof body.current_iteration?.change_title === 'string' ? body.current_iteration.change_title : null);
const progressLabel = active
  ? `${active} — ${reportedTitle || stageTitle}`
  : body.task_status === 'STAGE_VALIDATING'
    ? `${stageId} — full test suite validation`
    : body.task_status === 'STAGE_READY'
      ? `${stageId} — stage ready for Worker validation`
      : body.task_status === 'STAGE_PASSED'
        ? `${stageId} — stage passed`
        : lastLabel || `${stageId} — ${stageTitle}`;
const complete = completed.length === cfg.stage_count &&
  cfg.stage_order.every((id,i) => completed[i] === id);
let publicStatus = body.task_status || 'UNKNOWN';
if (complete && body.task_status === 'COMPLETE') publicStatus = 'COMPLETE';
else if (complete && body.task_status === 'STAGE_PASSED') publicStatus = 'READY_FOR_REVIEW';
else if (active) publicStatus = 'CODEX_ITERATION_ACTIVE';
else if (body.task_status === 'STAGE_VALIDATING') publicStatus = 'FULL_SUITE_ACTIVE';
const terminal = (complete && ['STAGE_PASSED','COMPLETE'].includes(body.task_status)) ||
  ['COMPLETE','HUMAN_REQUIRED','SYNC_REQUIRED','FAILED','RECOVERY_REQUIRED'].includes(body.task_status);
const keepPolling = !terminal && elapsed < cfg.max_monitor_minutes;
return result({
  status:elapsed >= cfg.max_monitor_minutes && !terminal ? 'MONITOR_TIME_LIMIT' : publicStatus,
  progress_label:progressLabel,
  active_iteration_id:active,
  current_title_source:active ? (reportedTitle ? 'WORKER_REPORTED' : 'STAGE_FALLBACK') : 'NOT_ACTIVE',
  current_stage_id:stageId,
  current_stage_title:stageTitle,
  last_completed_iteration:lastLabel,
  completed_stages:completed,
  stage_count:cfg.stage_count,
  next_action:body.next_action || null,
  last_stage_validation:body.last_stage_validation?.validation_status || body.last_stage_validation?.status || null,
  raw_task_status:body.task_status,
  manual_gate_required:false,
  elapsed_minutes:Math.round(elapsed*10)/10,
  monitoring:keepPolling,
  summary:publicStatus === 'READY_FOR_REVIEW'
    ? 'All ten stages passed. Await separate final HUMAN review before COMPLETE.'
    : terminal ? 'Monitoring stopped; inspect Worker Task State before further action.'
    : 'Read-only polling. No changes executed.'
});
